pm.test("Status code is 409 Conflict", function () {
    pm.response.to.have.status(409);
});

pm.test("Error code is SPEAKER_HAS_EVENTS", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("error");
    pm.expect(json.error.status).to.eql(409);
    pm.expect(json.error.code).to.eql("SPEAKER_HAS_EVENTS");
    pm.expect(json.error).to.have.property("message");
    pm.expect(json.error).to.have.property("timestamp");
});

pm.test("Status code is 204 No Content", function () {
    pm.response.to.have.status(204);
});

pm.test("Response body is empty", function () {
    pm.expect(pm.response.text()).to.eql("");
});

pm.test("Status code is 404 Not Found", function () {
    pm.response.to.have.status(404);
});

pm.test("Error code is SPEAKER_NOT_FOUND", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("error");
    pm.expect(json.error.status).to.eql(404);
    pm.expect(json.error.code).to.eql("SPEAKER_NOT_FOUND");
    pm.expect(json.error).to.have.property("message");
    pm.expect(json.error).to.have.property("timestamp");
});
